// Originally generated by Lovable; customised to verify the access token
// before any server function runs. Keep the verification if this file is
// regenerated.
import { createMiddleware } from "@tanstack/react-start";
import { getRequest } from "@tanstack/react-start/server";
import { createClient, type JwtPayload } from "@supabase/supabase-js";
import type { Database } from "./types";

function isNewSupabaseApiKey(value: string): boolean {
  return value.startsWith("sb_publishable_") || value.startsWith("sb_secret_");
}

function createSupabaseFetch(supabaseKey: string): typeof fetch {
  return (input, init) => {
    const headers = new Headers(
      typeof Request !== "undefined" && input instanceof Request ? input.headers : undefined,
    );

    if (init?.headers) {
      new Headers(init.headers).forEach((value, key) => headers.set(key, value));
    }

    // New Supabase API keys are opaque strings, not bearer JWTs.
    if (
      isNewSupabaseApiKey(supabaseKey) &&
      headers.get("Authorization") === `Bearer ${supabaseKey}`
    ) {
      headers.delete("Authorization");
    }

    headers.set("apikey", supabaseKey);
    return fetch(input, { ...init, headers });
  };
}

const UNAUTHORIZED = "Your session has expired. Please sign in again.";

/**
 * Verifies the caller's Supabase access token and exposes an RLS-scoped client.
 * Fails closed: any missing, malformed, expired or unverifiable token is rejected,
 * and disabled accounts (profiles.is_active = false) are refused.
 */
export const requireSupabaseAuth = createMiddleware({ type: "function" }).server(
  async ({ next }) => {
    const SUPABASE_URL = process.env.SUPABASE_URL;
    const SUPABASE_PUBLISHABLE_KEY = process.env.SUPABASE_PUBLISHABLE_KEY;

    if (!SUPABASE_URL || !SUPABASE_PUBLISHABLE_KEY) {
      const missing = [
        ...(!SUPABASE_URL ? ["SUPABASE_URL"] : []),
        ...(!SUPABASE_PUBLISHABLE_KEY ? ["SUPABASE_PUBLISHABLE_KEY"] : []),
      ];
      console.error(`[Supabase] Missing environment variable(s): ${missing.join(", ")}`);
      throw new Error("The server is not configured correctly. Please try again later.");
    }

    const request = getRequest();
    const authHeader = request?.headers?.get("authorization") ?? "";
    const match = /^Bearer\s+(\S+)$/i.exec(authHeader);
    const token = match?.[1];
    if (!token || token.split(".").length !== 3) {
      throw new Error(UNAUTHORIZED);
    }

    const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
      global: {
        fetch: createSupabaseFetch(SUPABASE_PUBLISHABLE_KEY),
        headers: {
          Authorization: `Bearer ${token}`,
        },
      },
      auth: {
        storage: undefined,
        persistSession: false,
        autoRefreshToken: false,
      },
    });

    // getClaims verifies the signature (JWKS for asymmetric keys, or the Auth
    // server for legacy symmetric keys) and the expiry.
    let claims: JwtPayload;
    try {
      const { data, error } = await supabase.auth.getClaims(token);
      if (error || !data?.claims) throw error ?? new Error("No claims");
      claims = data.claims;
    } catch (err) {
      console.warn("[auth] token verification failed:", err instanceof Error ? err.message : err);
      throw new Error(UNAUTHORIZED);
    }

    const userId = typeof claims.sub === "string" ? claims.sub : "";
    if (!userId || claims.role !== "authenticated") {
      throw new Error(UNAUTHORIZED);
    }

    const { data: profile, error: profileError } = await supabase
      .from("profiles")
      .select("is_active")
      .eq("id", userId)
      .maybeSingle();
    if (profileError) {
      console.error("[auth] profile lookup failed:", profileError.message);
      throw new Error("Could not verify your account. Please try again.");
    }
    if (profile && profile.is_active === false) {
      throw new Error("Your account has been disabled. Contact an administrator.");
    }

    return next({
      context: {
        supabase,
        userId,
        claims,
      },
    });
  },
);
